return [{
  json: {
    scanTimestamp: new Date().toISOString(),
    dryRun: String($env.FOLLOWUP_DRY_RUN || '').toLowerCase() === 'true',
    evolutionBaseUrl: $env.EVOLUTION_API_URL || 'https://groundedlungfish-evolution.cloudfy.live',
    evolutionInstance: $env.EVOLUTION_INSTANCE || 'backe%20-%20bruno',
    evolutionApiKey: $env.EVOLUTION_API_KEY || ''
  }
}];

const leads = $input.all();
return leads.map(item => ({
  json: {
    ...item.json,
    followupNumber: parseInt(item.json.followup_count) + 1,
    scanTimestamp: $input.first().json.scanTimestamp || new Date().toISOString()
  }
}));

const lead = $input.first().json;
const empresa = lead.empresa || 'sua empresa';
const followupMessages = {
  1: `Ola, ${lead.nome}! Tudo bem?\n\nVimos que voce demonstrou interesse nos nossos servicos de automacao para a ${empresa} e ainda nao conseguimos te atender.\n\nComo podemos te ajudar? Estamos disponiveis para conversar sobre como otimizar seu negocio.\n\nAguardamos seu retorno!`,
  2: `Oi, ${lead.nome}!\n\nPassando novamente para ver se podemos ajudar a ${empresa} com automacao e captacao de leads.\n\nSe ainda tiver interesse, e so responder essa mensagem. Caso contrario, tudo bem tambem!\n\nAbracos, equipe BACKE.co`
};

const messageText = followupMessages[lead.followupNumber] || followupMessages[1];

return [{
  json: {
    ...lead,
    followupMessage: messageText
  }
}];

const lead = $input.first().json;
return [{
  json: {
    leadId: lead.lead_id,
    phone: lead.telefone,
    nome: lead.nome,
    followupNumber: lead.followupNumber,
    message: lead.followupMessage,
    dryRun: true,
    sentAt: new Date().toISOString(),
    whatsappOk: true
  }
}];

const lead = $input.first().json;
const httpResult = $('HTTP - Enviar WhatsApp Follow-up').first();
const httpError = httpResult.json?.error || httpResult.error;

return [{
  json: {
    leadId: lead.lead_id,
    phone: lead.telefone,
    nome: lead.nome,
    followupNumber: lead.followupNumber,
    message: lead.followupMessage,
    dryRun: false,
    sentAt: new Date().toISOString(),
    whatsappOk: !httpError,
    whatsappError: httpError || null
  }
}];

const results = $input.all();
const sent = results.filter(r => r.json.whatsappOk).length;
const failed = results.filter(r => !r.json.whatsappOk).length;
const markedCold = results.filter(r => parseInt(r.json.followupNumber) >= 2).length;

return [{
  json: {
    scanComplete: true,
    totalProcessed: results.length,
    followupsSent: sent,
    followupsFailed: failed,
    leadsMarkedCold: markedCold,
    completedAt: new Date().toISOString()
  }
}];

return [{
  json: {
    scanComplete: true,
    totalProcessed: 0,
    followupsSent: 0,
    followupsFailed: 0,
    leadsMarkedCold: 0,
    noEligibleLeads: true,
    completedAt: new Date().toISOString()
  }
}];
